// The PIN gate. Every case here is a defect that shipped at some point.
import AsyncStorage from '@react-native-async-storage/async-storage';
import { verifyPasscode, savePasscode, clearPasscode } from '../../src/gen/features/passcode';

const MAX = 3;

beforeEach(async () => {
  await AsyncStorage.clear();
  await clearPasscode();
});

it('rejects any code when no passcode is stored (fails CLOSED)', async () => {
  // Previously returned 'ok': clearing app data unlocked the app.
  await expect(verifyPasscode('1234')).resolves.toBe('wrong');
});

it('accepts the stored passcode', async () => {
  await savePasscode('1234');
  await expect(verifyPasscode('1234')).resolves.toBe('ok');
});

it('locks after MAX_ATTEMPTS wrong codes', async () => {
  await savePasscode('1234');
  for (let i = 0; i < MAX - 1; i++) {
    await expect(verifyPasscode('0000')).resolves.toBe('wrong');
  }
  await expect(verifyPasscode('0000')).resolves.toBe('locked');
});

it('STAYS locked — the lockout does not hand back a fresh budget', async () => {
  // Previously attempts was zeroed on lockout, so an attacker got MAX guesses
  // per round, forever.
  await savePasscode('1234');
  for (let i = 0; i < MAX; i++) await verifyPasscode('0000');
  await expect(verifyPasscode('0000')).resolves.toBe('locked');
  await expect(verifyPasscode('0000')).resolves.toBe('locked');
});

it('does not accept the CORRECT code once locked out', async () => {
  await savePasscode('1234');
  for (let i = 0; i < MAX; i++) await verifyPasscode('0000');
  await expect(verifyPasscode('1234')).resolves.toBe('locked');
});

it('a correct code clears the budget', async () => {
  await savePasscode('1234');
  await verifyPasscode('0000');
  await expect(verifyPasscode('1234')).resolves.toBe('ok');
  // budget reset: a full run of wrong codes is needed to lock again
  for (let i = 0; i < MAX - 1; i++) {
    await expect(verifyPasscode('0000')).resolves.toBe('wrong');
  }
});
